void yRoots(float p[5], float begin, float end, out float roots[5]) {
  int n = yDegree(p);
  if (n == 4)
    yRoots4(p, begin, end, roots);
  else if (n == 3)
    yRoots3(p, begin, end, roots);
  else if (n == 2)
    yRoots2(p, begin, end, roots);
