void powerCoefficients(vec4 a, vec4 b, vec4 c, float level, out float p[5]) {
  p[0] = form(a, a, level);
  p[1] = 2. * form(a, b, level);
  p[2] = form(b, b, level) + 2. * form(a, c, level);
  p[3] = 2. * form(b, c, level);
  p[4] = form(c, c, level);
