float coeff(Poly p, int i) {
  return i == 4 ? p.b : p.a[i];
}
Poly derivative(Poly p) {
  return Poly(vec4(p.a.y - p.a.x, p.a.z - p.a.y, p.a.w - p.a.z, p.b - p.a.w), 0.);
