    float n1 = optics(before).y, n2 = optics(after).y, F = fresnel(ci, n1, n2);
    vec3 t = refract(d, n, n1 / n2);
    light += weight * mat.x * surfaceLight(p, n, d, surface);
    weight *= 1. - mat.x;
    if (dot(t, t) < 1e-10 && !tangent) {
      o = p + n * eps;
      d = r;
      roughness = mat.z;
      continue;
    }
    light += weight * F * roughEnvironment(r, mat.z);
    weight *= 1. - F;
    if (tangent) {
      o = p + d * eps * 4.;
      continue;
